# Vendored and trimmed from jiggle_version/update.py (jiggle-version 2.1.1).
"""Update version strings in source files.

``update_python_file`` is tightened relative to upstream (see below) but stays
pure ``re``. ``update_pyproject_toml`` uses TOML Kit to preserve comments,
whitespace and valid TOML syntax while updating the project version.

``update_setup_cfg`` is intentionally not vendored: ``bump_version_files`` never
calls it.

Two safety changes vs upstream, both from the bug where a bump rewrote
``__version__`` in installed third-party packages:

* **Generated files are refused.** A file carrying a build-backend marker such
  as ``file generated by setuptools-scm`` has its version owned by someone
  else's build; :func:`update_python_file` leaves it alone.
* **The bare ``version = "..."`` form is anchored.** Upstream matched any
  ``version =`` assignment anywhere in the file, which is what turned the
  generated ``__version__ = version = '9.1.1'`` line in every ``_version.py``
  into a target. It is now only honored in ``setup.py``, the file it exists for.

:func:`update_python_file` also keeps a rewritten file self-consistent: a
``version_tuple``/``__version_tuple__`` beside the string is updated to match
rather than left describing the old version.
"""

from __future__ import annotations

import logging
import re
from pathlib import Path

import tomlkit

from changelogmanager.file_updates import atomic_write_text

LOGGER = logging.getLogger(__name__)

# ``__version__ = "1.0"`` and the chained ``__version__ = version = "1.0"``.
# The chain is captured into group 1 so only the string literal is replaced.
_PYTHON_DUNDER_VERSION_RE = re.compile(r"""(?m)^(\s*__version__\s*(?::[^=\n]+)?=\s*(?:version\s*=\s*)*)(['"])(.*?)(\2)""")
# Only applied to setup.py -- see the module docstring. Anchored to the start of
# a line so it cannot match the trailing half of ``__version__ = version = '...'``.
_PYTHON_SETUP_VERSION_RE = re.compile(r"""(?m)^(\s*version\s*=\s*)(['"])(.*?)(\2)""")
# ``__version_tuple__ = version_tuple = (9, 1, 1)`` -- kept in step with the
# string so a rewritten file never contradicts itself.
_VERSION_TUPLE_RE = re.compile(
    r"""(?m)^(\s*(?:__version_tuple__|version_tuple)\s*(?::[^=\n]+)?=\s*)"""
    r"""(?P<chain>(?:(?:__version_tuple__|version_tuple)\s*=\s*)*)"""
    r"""\((?P<body>[^()\n]*)\)"""
)

# Markers left by build backends that generate the file. Their version is owned
# by the build, not by the project's source tree; rewriting it corrupts an
# installed package and is silently undone on the next build.
_GENERATED_FILE_MARKERS = (
    "file generated by setuptools-scm",
    "file generated by setuptools_scm",
    "file generated by vcs-versioning",
    "generated by versioneer",
    "this file is automatically generated",
    "automatically generated by",
    "do not change, do not track in version control",
    "don't change, don't track in version control",
)


def is_generated_version_file(content: str) -> bool:
    """True if ``content`` carries a build backend's "generated file" marker."""
    head = content[:2048].lower()
    return any(marker in head for marker in _GENERATED_FILE_MARKERS)


def _version_tuple_literal(new_version: str) -> str:
    """Render ``new_version`` as the body of a setuptools-scm version tuple.

    ``"1.2.3"`` -> ``1, 2, 3``; ``"1.2.3rc1"`` -> ``1, 2, 3, 'rc1'``. Returns
    ``""`` when the version does not decompose cleanly, which tells the caller
    to leave the tuple alone.
    """
    chunks = new_version.split(".")
    parts: list[str] = []
    for index, chunk in enumerate(chunks):
        if chunk.isdigit():
            parts.append(chunk)
            continue
        # A trailing chunk like "3rc1" splits into the number and a suffix.
        digits = ""
        for char in chunk:
            if not char.isdigit():
                break
            digits += char
        suffix = chunk[len(digits) :]
        if not digits and not suffix:
            return ""
        if suffix and index != len(chunks) - 1:
            # A suffix mid-version (e.g. "1.rc1.2") is not a shape we model.
            return ""
        if digits:
            parts.append(digits)
        if suffix:
            parts.append(repr(suffix))
    return ", ".join(parts)


def update_pyproject_toml(file_path: Path, new_version: str) -> bool:
    """Update the declared version without discarding TOML comments or layout.

    A missing static version is a deliberate no-op (e.g. dynamic versioning).
    Callers with explicit ownership can distinguish this using the return value.
    """
    text = file_path.read_bytes().decode("utf-8")
    document = tomlkit.parse(text)
    for keys in (("project",), ("tool", "setuptools")):
        table = document
        for key in keys:
            table = table.get(key, {})
        if "version" not in table:
            continue
        if not isinstance(table["version"], str):
            raise ValueError(f"Version in {file_path} must be a string")
        table["version"] = new_version
        atomic_write_text(file_path, tomlkit.dumps(document))
        return True
    return False


def update_python_file(file_path: Path, new_version: str) -> bool:
    """Update the version in a Python file (``__version__`` or ``setup.py``).

    Returns True if the file was rewritten. A file generated by a build backend
    is refused (returns False, file untouched); so is one with no version
    assignment to change.
    """
    content = file_path.read_text(encoding="utf-8")

    if is_generated_version_file(content):
        LOGGER.info(
            "Refusing to bump %s: it is marked as generated by a build backend",
            file_path,
        )
        return False

    def replacer(match: re.Match[str]) -> str:
        return f"{match.group(1)}{match.group(2)}{new_version}{match.group(2)}"

    new_content, dunder_count = _PYTHON_DUNDER_VERSION_RE.subn(replacer, content)

    setup_count = 0
    if file_path.name == "setup.py":
        new_content, setup_count = _PYTHON_SETUP_VERSION_RE.subn(replacer, new_content)

    if dunder_count == 0 and setup_count == 0:
        return False

    new_content = _sync_version_tuple(new_content, new_version)
    atomic_write_text(file_path, new_content)
    return True


def _sync_version_tuple(content: str, new_version: str) -> str:
    """Rewrite any ``version_tuple`` assignment to agree with ``new_version``."""
    body = _version_tuple_literal(new_version)
    if not body:
        return content

    def replacer(match: re.Match[str]) -> str:
        return f"{match.group(1)}{match.group('chain')}({body})"

    return _VERSION_TUPLE_RE.sub(replacer, content)
